import { useEffect, useState } from "react";
import axios from "axios";

function AdminEnquiries() {

  const [messages, setMessages] = useState([]);
  const [replyText, setReplyText] = useState({});

  useEffect(() => {
    fetchMessages();
  }, []);

  const fetchMessages = async () => {
    const res = await axios.get("http://localhost:5000/api/provider/contact");
    setMessages(res.data);
  };

  // ✅ MARK AS RESOLVED
  const markResolved = async (id) => {
    await axios.put(`http://localhost:5000/api/provider/contact/${id}`, {
      status: "resolved",
      reply: replyText[id] || ""
    });

    fetchMessages();
  };

  // ✅ REPLY SEND
  const sendReply = async (id) => {
    await axios.put(`http://localhost:5000/api/provider/contact/${id}`, {
      status: "resolved",
      reply: replyText[id]
    });

    alert("Reply sent!");
    fetchMessages();
  };

  return (
    <div className="enquiries-container">

      <h2 className="enquiries-title">Contact Enquiries</h2>

      <table className="enquiries-table">

        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Subject</th>
            <th>Message</th>
            <th>Status</th>
            <th>Reply</th>
            <th>Action</th>
          </tr>
        </thead>

        <tbody>

          {messages.map((msg) => (

            <tr key={msg.contact_id}>

              <td>{msg.name}</td>
              <td>{msg.email}</td>
              <td>{msg.subject}</td>
              <td className="message-cell">{msg.message}</td>

              <td>
                <span style={{
                  color: msg.status === "resolved" ? "green" : "orange"
                }}>
                  {msg.status}
                </span>
              </td>

              {/* REPLY INPUT */}
              <td>
                <input
                  type="text"
                  placeholder="Type reply..."
                  value={replyText[msg.contact_id] || ""}
                  onChange={(e) =>
                    setReplyText({
                      ...replyText,
                      [msg.contact_id]: e.target.value
                    })
                  }
                />
              </td>

              {/* ACTIONS */}
              <td>

                <button onClick={() => sendReply(msg.contact_id)}>
                  Reply
                </button>

                <button onClick={() => markResolved(msg.contact_id)}>
                  Resolve
                </button>

              </td>

            </tr>

          ))}

        </tbody>

      </table>

    </div>
  );
}

export default AdminEnquiries;
